/**
 * The client surface `apps/web` imports, pinned.
 *
 * `packages/contracts/generated/auth-client.ts` is a barrel over
 * `packages/contracts/client/`, generated by `deno task contracts:generate`.
 * Because it is generated, renaming a client function would quietly rewrite it
 * and `contracts:check` would still pass — so the names themselves are written
 * down here, once, and a rename has to be a deliberate edit to this list.
 *
 * The second test is the wiring: every function is called against a stubbed
 * `fetch`, and the path it asks for has to be one the published document
 * describes. That is what proves the barrel re-exports a working client and
 * not just a matching set of names.
 */

import * as client from "./generated/auth-client.ts";
import document from "./openapi/openapi.json" with { type: "json" };
